(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["clinical-pathophysiology-i-exam-2"]={"title":"Clinical Pathophysiology I Exam 2","sections":[{"id":"l6-chd","title":"L6 · Coronary Heart Disease & Ischemia","style":"--acc:#6e1f2f;--acc-bg:#ebe0e2;--acc-zebra:#f5eff0;--acc-ink:#561825"},{"id":"l6-plaque","title":"L6 · Lipoproteins, Atherosclerosis & Plaque","style":"--acc:#8a5a14;--acc-bg:#efe8de;--acc-zebra:#f7f3ef;--acc-ink:#6c4610"},{"id":"l6-acs","title":"L6 · Angina & Acute Coronary Syndrome","style":"--acc:#a23a4c;--acc-bg:#f2e3e6;--acc-zebra:#f8f1f2;--acc-ink:#7e2d3b"},{"id":"l6-valves","title":"L6 · Valve Disease","style":"--acc:#2f5f6b;--acc-bg:#e2e9ea;--acc-zebra:#f0f4f5;--acc-ink:#254a53"},{"id":"l6-myo","title":"L6 · Infective, Myocardial & Pericardial","style":"--acc:#5a3a6e;--acc-bg:#e8e3eb;--acc-zebra:#f3f1f5;--acc-ink:#462d56"},{"id":"l7-structure","title":"L7 · Vessel Anatomy & Function","style":"--acc:#1f5a73;--acc-bg:#e0e8eb;--acc-zebra:#eff3f5;--acc-ink:#18465a"},{"id":"l7-wall","title":"L7 · Wall Injury, Vessel Size & Blood Pressure","style":"--acc:#2e6b4f;--acc-bg:#e2eae6;--acc-zebra:#f0f5f3;--acc-ink:#24533e"},{"id":"l7-athero","title":"L7 · Arteriosclerosis & Atherosclerosis","style":"--acc:#7a4a1f;--acc-bg:#ece6e0;--acc-zebra:#f6f2ef;--acc-ink:#5f3a18"},{"id":"l7-aneurysm","title":"L7 · Aneurysm & Dissection","style":"--acc:#6b2d5c;--acc-bg:#eae2e8;--acc-zebra:#f5f0f4;--acc-ink:#532348"},{"id":"l7-other","title":"L7 · Other Arterial Disease & Veins","style":"--acc:#3d4f7a;--acc-bg:#e4e6ec;--acc-zebra:#f1f3f6;--acc-ink:#303e5f"},{"id":"l8-basics","title":"L8 · Immunity Basics & Blood Cells","style":"--acc:#4a2f6e;--acc-bg:#e6e2eb;--acc-zebra:#f2f0f5;--acc-ink:#3a2556"},{"id":"l8-antibodies","title":"L8 · B Cells & Antibodies","style":"--acc:#6a4fa3;--acc-bg:#eae6f2;--acc-zebra:#f5f3f9;--acc-ink:#533e7f"},{"id":"l8-tcells","title":"L8 · T Cells & Hypersensitivity","style":"--acc:#7a2f5a;--acc-bg:#ece2e8;--acc-zebra:#f6f0f3;--acc-ink:#5f2546"},{"id":"l8-complement","title":"L8 · Complement, Immunodeficiency & Age","style":"--acc:#2f4f6e;--acc-bg:#e2e6eb;--acc-zebra:#f0f3f5;--acc-ink:#253e56"},{"id":"l9-arf","title":"L9 · Respiratory Failure, Pulmonary Hypertension & Cancer","style":"--acc:#1f5a73;--acc-bg:#e0e8eb;--acc-zebra:#eff3f5;--acc-ink:#18465a"},{"id":"l9-obstructive","title":"L9 · Obstructive Disease & Asthma","style":"--acc:#2e6b4f;--acc-bg:#e2eae6;--acc-zebra:#f0f5f3;--acc-ink:#24533e"},{"id":"l9-restrictive","title":"L9 · Restrictive Disease & Acute Respiratory Distress Syndrome","style":"--acc:#7a4a1f;--acc-bg:#ece6e0;--acc-zebra:#f6f2ef;--acc-ink:#5f3a18"},{"id":"l9-pleura","title":"L9 · Pleura, Sleep Apnea & Pneumonia","style":"--acc:#3d4f7a;--acc-bg:#e4e6ec;--acc-zebra:#f1f3f6;--acc-ink:#303e5f"}],"rows":[{"t":"Coronary heart disease","d":"Insufficient delivery of oxygenated blood to the myocardium because of ATHEROSCLEROTIC coronary arteries. About 50% of cardiovascular deaths. Also called ischemic heart disease, coronary artery disease.","s":0},{"t":"Ischemia = supply vs demand","d":"Begins when oxygen SUPPLY &lt; DEMAND → less ATP (adenosine triphosphate). Causes abnormal function AND abnormal rhythms; prolonged → irreversible damage.","s":0},{"t":"Supply falls","d":"Large plaques · acute platelet aggregation then thrombosis · VASOSPASM · abnormal microcirculation · poor perfusion pressure.","s":0},{"t":"Demand rises","d":"Workload = HEART RATE · PRELOAD · AFTERLOAD · CONTRACTILITY. Raise any one → more oxygen demand.","s":0},{"t":"Etiologies","d":"ATHEROSCLEROSIS behind almost all → predisposes to thrombosis, vasospasm, endothelial dysfunction. Microcirculation: small-vessel endothelium regulates flow abnormally. Uncommon: low blood oxygen content (respiratory); poor perfusion (hypotension, hypovolemia).","s":0},{"t":"Major risk factors","d":"Age · family history · abnormal lipids · smoking · hypertension · diabetes mellitus · obesity.","s":0},{"t":"Probable risk factors","d":"Male sex · HOMOCYSTEINE · high-sensitivity C-reactive protein.","s":0},{"t":"Collateral circulation","d":"Develops when plaque builds over YEARS — why slow occlusion is tolerated better than sudden.","s":0},{"t":"Flow tracks demand","d":"Myocardial oxygen consumption and blood flow correspond NEARLY LINEARLY; METABOLIC SIGNALS are the principal determinants of delivery.","s":0},{"t":"Coronary anatomy","d":"LEFT MAIN → left anterior descending (anterior interventricular) + CIRCUMFLEX. RIGHT CORONARY → marginal + posterior interventricular.","s":0},{"t":"Frank–Starling","d":"More diastolic filling → more ejected. Force ∝ initial sarcomere length (preload). Maximal force at 2.6 micrometers, rarely exceeded in the normal heart.","s":0},{"t":"Low-density lipoprotein","d":"Cholesterol-rich → HIGHEST risk.","s":1},{"t":"Very-low-density lipoprotein","d":"Triglyceride-rich → INCREASES risk.","s":1},{"t":"High-density lipoprotein","d":"DECREASES risk — carries cholesterol BACK TO THE LIVER, away from plaque.","s":1},{"t":"Familial hypercholesterolemia","d":"Common single-gene hyperlipidemia (classically taught as the most common). Defective LOW-DENSITY LIPOPROTEIN RECEPTOR on liver cells → liver cannot clear cholesterol.","s":1},{"t":"Homocysteine","d":"Amino acid from METHIONINE → CYSTEINE. Atherogenic + prothrombotic: intimal thickening, elastic lamina disruption, smooth muscle hypertrophy, platelet accumulation, platelet-rich occlusive thrombus.","s":1},{"t":"Plaque sequence","d":"ENDOTHELIAL INJURY (wall stress, toxins, inflammation, hyperlipidemia) → permeable endothelium, leukocytes recruited → low-density lipoprotein leaks in and is OXIDIZED → FOAM CELLS → mediators + growth factor → smooth muscle proliferation → LIPID CORE → collagen/fibrin CAP.","s":1},{"t":"75%","d":"Occlusion at which blood flow is COMPROMISED.","s":1},{"t":"Vulnerable plaque (slide 24, image only)","d":"LARGE lipid core · THIN fibrous cap · rich in MACROPHAGES · increased MMPs (matrix metalloproteinases) · POOR in smooth muscle · LOW-GRADE stenosis.","s":1},{"t":"Stable vs vulnerable","d":"Stable: thick cap, small core, many smooth muscle cells. Vulnerable: thin cap, large core, many macrophages. Smooth muscle BUILDS the cap; macrophages DIGEST it.","s":1},{"t":"Why plaques rupture","d":"Composition + mechanical stress. Trigger: SHEAR from high-velocity flow through a severe stenosis. VASA VASORUM capillaries hemorrhage → pressure builds inside the plaque.","s":1},{"t":"Rupture consequences","d":"Exposed subendothelial proteins → platelet aggregation → THROMBUS; EMBOLI block smaller vessels downstream.","s":1},{"t":"Coronary syndromes","d":"CHRONIC: stable angina, ischemic cardiomyopathy. ACUTE: unstable angina, myocardial infarction. Classified by severity and onset.","s":2},{"t":"Angina pectoris","d":"Intermittent ischemia NOT enough to kill cells; when demand rises; may cause pulmonary congestion.","s":2},{"t":"Stable (typical)","d":"MOST COMMON. Fixed stenosis → ischemia only under increased WORKLOAD.","s":2},{"t":"Prinzmetal (variant)","d":"VASOSPASM (cause unknown). Unpredictable; typically at REST, not with exertion.","s":2},{"t":"Unstable (crescendo)","d":"May progress to acute ischemia → counted with the ACUTE coronary syndromes.","s":2},{"t":"Acute coronary syndrome","d":"Unstable angina + myocardial infarction (hard to tell apart clinically). Pain longer than typical angina; PLAQUE RUPTURE + ACUTE THROMBOSIS.","s":2},{"t":"Infarction mechanism","d":"Prolonged/total loss of flow → NECROSIS or APOPTOSIS. Thrombus on a cracked plaque → platelet plug → clotting cascade → occlusion. Outcome depends on COLLATERALS, WORKLOAD, TIME.","s":2},{"t":"Occlusion timeline","d":"Immediately: ATP depleted. Few minutes: cannot contract. AFTER 30 MINUTES: irreversible necrosis.","s":2},{"t":"Location","d":"Nearly all in LEFT VENTRICLE. Left anterior descending 40–50% · right coronary 30–40% · left circumflex 15–20%.","s":2},{"t":"Gross changes","d":"First several hours: hard to see by eye (slide: 6 h) · 18–24 h: paler · then yellow, soft, red vascular border · 1–2 weeks: necrotic tissue removed · by 6 weeks: fibrous scar.","s":2},{"t":"Stenosis vs regurgitation","d":"STENOSIS = fails to OPEN → PRESSURE work, gradient across valve. REGURGITATION = fails to CLOSE → VOLUME work.","s":3},{"t":"Stenosis facts","d":"Hemodynamics affected at 50% closure; slow → compensatory HYPERTROPHY. Causes: RHEUMATIC scarring, aging CALCIFICATION.","s":3},{"t":"Regurgitation facts","d":"Acute: infection or PAPILLARY MUSCLE RUPTURE. Important causes: rheumatic heart disease, infective endocarditis, degenerative valve changes, aortic root dilation.","s":3},{"t":"Mitral stenosis","d":"DIASTOLIC left atrial &gt; left ventricular gradient. Left atrial congestion/pressure ↑, pulmonary pressure ↑, stroke volume ↓ → pulmonary hypertension → right heart failure. Late: ATRIAL FIBRILLATION, atrial enlargement, ATRIAL CLOTS.","s":3},{"t":"Mitral regurgitation","d":"SYSTOLIC backflow into atrium. HIGH AFTERLOAD INCREASES it. Atrium AND ventricle dilate + hypertrophy; severe → left heart failure.","s":3},{"t":"Mitral valve prolapse","d":"BALLOONING into left atrium in systole. Usually silent; sometimes some regurgitation.","s":3},{"t":"Aortic stenosis","d":"Most often AGE-RELATED CALCIFICATION; common with BICUSPID valve (slide: clinically apparent over 79). Systolic left ventricle–aortic gradient → LEFT VENTRICULAR HYPERTROPHY → ischemia and ANGINA → failure.","s":3},{"t":"Aortic regurgitation","d":"DIASTOLIC leak back into left ventricle. AORTIC ROOT DILATION common (aging, connective tissue disease). Left ventricle hypertrophies + dilates; AORTIC DIASTOLIC PRESSURE FALLS (blood leaks back).","s":3},{"t":"Timing rule","d":"DIASTOLE: mitral stenosis, aortic regurgitation. SYSTOLE: mitral regurgitation, prolapse, aortic stenosis.","s":3},{"t":"Rheumatic heart disease","d":"After GROUP A BETA-HEMOLYTIC STREPTOCOCCUS. IMMUNE attack by CROSS-REACTIVITY; HLA (human leukocyte antigen) predisposition. All layers → carditis. Valves: swelling, erosions, platelets + fibrin, then SCARRING and SHORTENING.","s":4},{"t":"Infective endocarditis","d":"Invasion + colonization of endocardium; BLOODSTREAM INVASION is a prerequisite. VEGETATIONS = organisms in FIBRIN → dysfunction + EMBOLI. Commonest: Streptococcus, Staphylococcus aureus.","s":4},{"t":"Subacute endocarditis","d":"Insidious; needs a PREEXISTING valve lesion. LESS VIRULENT organisms (typically Streptococcus) cannot attack a healthy endocardium. S. aureus is ACUTE, not subacute (the slide lists it here; Robbins pairs it with the acute form).","s":4},{"t":"Myocarditis","d":"Inflammation + leukocyte infiltration + necrosis. Microbes (most often viruses, classically COXSACKIEVIRUS), immune disease, physical agents. Left ventricular dysfunction, chambers sometimes dilated, edematous muscle, endocardium usually NORMAL.","s":4},{"t":"Dilated cardiomyopathy","d":"Also 'congested'. Dilation of one or both ventricles → failure. ALCOHOL · GENETICS · PREGNANCY · POST-VIRAL.","s":4},{"t":"Hypertrophic cardiomyopathy","d":"Thick, HYPERKINETIC muscle. OUTFLOW OBSTRUCTION + impaired DIASTOLIC FILLING.","s":4},{"t":"Restrictive cardiomyopathy","d":"Stiff, FIBROTIC, noncompliant (e.g. AMYLOIDOSIS) → restricted filling → low stroke volume → failure.","s":4},{"t":"Pericardial effusion types","d":"SEROUS transudate (heart failure, hypoproteinemia) · SEROSANGUINOUS (blunt trauma, heart surgery, cardiopulmonary resuscitation) · CHYLOUS (lymph obstruction) · BLOOD/hemopericardium (penetrating trauma).","s":4},{"t":"Tamponade","d":"Fluid, especially if it collects quickly, COMPRESSES chambers from outside → filling impaired. Life-threatening.","s":4},{"t":"Pericarditis","d":"ACUTE: mostly idiopathic, mostly VIRAL. CHRONIC: ADHESIVE mediastinopericarditis (heart stuck to mediastinum → workload ↑) or CONSTRICTIVE (dense scarred sac = STIFF CAGE → impaired diastolic filling).","s":4},{"t":"Not in the deck","d":"Objective m (blood pressure regulation) → see Lecture 7. Objective n (conduction system): no slide; only ischemia → abnormal rhythms, mitral stenosis → atrial fibrillation.","s":4},{"t":"Five components","d":"ARTERIES high pressure, strong walls, fast flow → ARTERIOLES control release into capillaries (main resistance, 'small but mighty') → CAPILLARIES exchange → VENULES collect → VEINS return blood, RESERVOIR, low pressure, thin walls.","s":5},{"t":"Three layers","d":"INTIMA: endothelium on basement membrane + thin matrix. MEDIA: elastin + smooth muscle 'like tree rings', expand in systole, recoil in diastole. ADVENTITIA: loose connective tissue, nerves, its own small arterioles in large vessels.","s":5},{"t":"Capillaries","d":"NO MEDIA. ≈ red cell diameter. Large cross-section, LOW flow → easy exchange. Densest in MYOCARDIUM and BRAIN. Pericytes around them.","s":5},{"t":"Capillary types","d":"CONTINUOUS (least permeable; blood–brain barrier) · FENESTRATED (kidney glomeruli, small intestine) · SINUSOIDAL (leakiest; liver, marrow, spleen, endocrine).","s":5},{"t":"Functions","d":"Nutrients in · wastes out · hormones carried · HOMEOSTASIS of tissue fluid.","s":5},{"t":"Loops","d":"PULMONARY: right heart → lungs. SYSTEMIC: left heart → tissues → right heart. Artery = AWAY from heart, so pulmonary artery carries deoxygenated blood.","s":5},{"t":"Veins hold","d":"About 66% of total blood volume.","s":5},{"t":"Healthy endothelium","d":"NONTHROMBOGENIC; modulates medial tone (resistance); METABOLIZES ANGIOTENSIN; regulates inflammation; controls smooth muscle growth.","s":6},{"t":"Smooth muscle cells","d":"Predominant media cell. Proliferate; make collagen, elastin, proteoglycans, growth factors, cytokines; constrict/dilate.","s":6},{"t":"Neointimal hyperplasia","d":"Injury → smooth muscle MIGRATES INTO INTIMA, proliferates, makes matrix; endothelium regrows with LESS NITRIC OXIDE; platelets activate; leukocytes recruited → thick intima, NARROW LUMEN. Same response to ANY injury.","s":6},{"t":"The twofold problem","d":"Thicker intima narrows the lumen AND lost nitric oxide (a vasodilator) lets it constrict.","s":6},{"t":"Two mechanisms","d":"NARROWING (progressive: atherosclerosis; precipitous: thrombosis, embolism) or WEAKENING (dilation, rupture).","s":6},{"t":"Size tends to predict disease","d":"Tendencies, not rules (atherosclerosis also affects the aorta). LARGE elastic (aorta 2–3.5 cm) → ANEURYSM (elastic loss). MEDIUM muscular (coronary 3–4 mm, renal) → ATHEROSCLEROSIS. SMALL (≤2 mm) + ARTERIOLES (20–100 micrometers) → HYPERTENSION.","s":6},{"t":"Blood pressure","d":"= CARDIAC OUTPUT × VASCULAR RESISTANCE. Resistance set at ARTERIOLES (constrictors vs dilators). Output = rate × stroke volume; volume set by SODIUM (water follows sodium).","s":6},{"t":"Low pressure response","d":"Kidney RENIN (low afferent arteriolar pressure) → angiotensinogen → ANGIOTENSIN I → endothelial catabolism → ANGIOTENSIN II → smooth muscle tone ↑ + ALDOSTERONE ↑ (sodium resorption).","s":6},{"t":"Hypertension risks","d":"Atherosclerosis, congestive heart failure, renal failure, CEREBRAL HEMORRHAGE, AORTIC DISSECTION.","s":6},{"t":"Essential hypertension","d":"90–95%, idiopathic. Genetic + environmental. INSUFFICIENT RENAL SODIUM EXCRETION → volume ↑ → output ↑ → constriction → pressure ↑.","s":6},{"t":"Secondary hypertension","d":"RENOVASCULAR: renal artery stenosis → low afferent pressure → RENIN. PRIMARY HYPERALDOSTERONISM: a common cause.","s":6},{"t":"Arteriosclerosis","d":"'Hardening of the arteries': wall thickening + LOSS OF ELASTICITY. Four patterns below.","s":7},{"t":"Arteriolosclerosis","d":"Small arteries/arterioles; HYPERTENSION. HYALINE = protein-thickened glassy wall, narrow lumen. HYPERPLASTIC = ONION SKINNING (concentric smooth muscle).","s":7},{"t":"Fibromuscular intimal hyperplasia","d":"Muscular arteries; inflammation or mechanical injury; a healing response → IN-STENT RESTENOSIS; limits solid-organ transplants.","s":7},{"t":"Mönckeberg medial sclerosis","d":"CALCIFICATION OF THE MEDIA of muscular arteries; usually NOT clinically significant.","s":7},{"t":"Atherosclerosis","d":"'Gruel' + 'hardening'. MOST clinically relevant. Coronary, cerebral, peripheral disease; slide: about half of Western deaths (an older figure; roughly a third of United States deaths today).","s":7},{"t":"Risk factors","d":"Hyperlipidemia · LIPOPROTEIN(a) (altered low-density lipoprotein, independent of total cholesterol) · smoking · hypertension · diabetes · METABOLIC SYNDROME · C-reactive protein · FAMILY HISTORY = strong risk, classically taught as the most important · age · men + postmenopausal women.","s":7},{"t":"Sequence","d":"Injury → LOW-DENSITY LIPOPROTEIN accumulates → MONOCYTE adhesion → PLATELET adhesion → smooth muscle RECRUITED → proliferation, matrix, T cells → lipid → CALCIFICATION.","s":7},{"t":"Atheroma","d":"Intimal plaque into the lumen: SOFT LIPID CORE + FIBROUS CAP. Stable → ischemia; unstable → rupture, thrombosis, embolism.","s":7},{"t":"★ Peripheral arterial disease","d":"'Do know': stenosis → ischemia → CLAUDICATION when working muscle's demand rises.","s":7},{"t":"Aneurysm vs dissection","d":"ANEURYSM = localized abnormal DILATION. DISSECTION = blood enters a wall defect and TUNNELS through the MEDIA.","s":8},{"t":"Shapes","d":"TRUE saccular (focal bulge, 'berry') · TRUE fusiform (whole circumference) · FALSE (ruptured wall, hematoma held by extravascular tissue) · DISSECTION (intimal tear splits media).","s":8},{"t":"Weakening ≠ rupture","d":"An aneurysm is a WEAK wall, not a ruptured one; rupture risk rises with SIZE (in lecture: under 4 cm rarely, over 5.5 cm very high).","s":8},{"t":"Pathogenesis","d":"Poor connective tissue (defective collagen; abnormal transforming growth factor signaling = MARFAN) · collagen degradation &gt; synthesis (inflammation, proteases) · smooth muscle LOSS (ischemia, hypertension, TERTIARY SYPHILIS).","s":8},{"t":"Predisposing","d":"Atherosclerosis · hypertension · smoking.","s":8},{"t":"Abdominal aortic aneurysm","d":"ATHEROSCLEROTIC; abdominal aorta + common iliac arteries.","s":8},{"t":"Thoracic aortic aneurysm","d":"HYPERTENSION; also Marfan, inflammation.","s":8},{"t":"Aortic dissection","d":"Laminar planes of MEDIA SPLIT → blood channel in the wall. HYPERTENSION = major risk factor.","s":8},{"t":"Cerebral saccular (berry)","d":"Thin/absent media; absent or fragmented internal elastic lamina. LACK OF ELASTIC LAMINA = main feature. Usually acquired.","s":8},{"t":"Fusiform / mycotic","d":"Fusiform: whole circumference (atherosclerosis). MYCOTIC: infected emboli from INFECTIVE ENDOCARDITIS (rare).","s":8},{"t":"Fibromuscular dysplasia","d":"Focal irregular thickening (hyperplasia + fibrosis of MEDIA and INTIMA) of medium/large muscular arteries → stenosis. RENAL arteries. 'STRING OF BEADS' on angiography; may dilate and rupture.","s":9},{"t":"Vasculitis","d":"Vessel wall inflammation, mostly SMALL vessels. Mechanisms: IMMUNE-MEDIATED or DIRECT INFECTIOUS INVASION. Large: giant cell arteritis. Medium: polyarteritis nodosa, Kawasaki. Small: ANCA (anti-neutrophil cytoplasmic antibody) necrotizing; immune complex (lupus, rheumatoid arthritis). Said to go light.","s":9},{"t":"Raynaud phenomenon","d":"EXAGGERATED VASOCONSTRICTION to COLD + STRESS, extremities. WHITE (spasm) → BLUE (anoxia) → RED (oxygenated blood returns).","s":9},{"t":"Arteriovenous fistula","d":"Direct artery–vein link BYPASSING CAPILLARIES: developmental, aneurysm rupturing into a vein, penetrating injury, inflammatory necrosis, surgical (hemodialysis access).","s":9},{"t":"Veins","d":"Larger lumen, THINNER MEDIA (capacitance), VALVES stop gravitational backflow.","s":9},{"t":"Varicose veins","d":"Dilated, tortuous; VALVE INSUFFICIENCY; chronic high intraluminal pressure + weak wall. Superficial (saphenous), legs; also pelvis/rectum.","s":9},{"t":"Esophageal varices / hemorrhoids","d":"Varices: submucosal distal esophageal veins from CIRRHOSIS + PORTAL HYPERTENSION. Hemorrhoids: varicose venous plexus at the ANORECTAL junction.","s":9},{"t":"Deep vein thrombosis","d":"Deep veins (femoral, popliteal, tibial); STASIS in a dilated vein. THIRD most common cardiovascular cause of death.","s":9},{"t":"Deep vein thrombosis risks","d":"Reduced flow (IMMOBILITY) · raised venous pressure · mechanical injury · raised viscosity (dehydration, thrombocytosis) · anatomy · hypercoagulable (cancer, sepsis, lupus, ORAL ESTROGEN).","s":9},{"t":"Virchow triad","d":"VESSEL WALL DAMAGE · ABNORMAL BLOOD FLOW (turbulence or stasis) · HYPERCOAGULABILITY.","s":9},{"t":"Clot fate","d":"Neutrophils + macrophages infiltrate fibrin; COLLAGEN replaces fibrin over weeks → less flow. Dislodges → EMBOLUS → PULMONARY ARTERY = pulmonary embolus.","s":9},{"t":"Immunity: 3 functions","d":"DEFENSE (resistance to invaders) · SURVEILLANCE (of self, for mutant or cancerous cells) · HOMEOSTASIS (removing cellular debris).","s":10},{"t":"Memory &amp; specificity","d":"Memory = faster, stronger adaptive response on RE-EXPOSURE. B- and T-cell receptors recognize particular EPITOPES; innate receptors recognize patterns shared by groups of organisms.","s":10},{"t":"Active vs passive","d":"ACTIVE: the body's own response after antigen exposure (natural = met naturally; artificial = VACCINATION). PASSIVE: PREFORMED antibodies transferred; immediate protection that declines.","s":10},{"t":"Passive examples","d":"Natural: maternal IgG through the PLACENTA, IgA in BREAST MILK. Artificial: tetanus and rabies immune globulin.","s":10},{"t":"Innate immunity","d":"Acts WITHOUT prior sensitization: skin and mucosal barriers, phagocytes, complement, interferons. Natural killer cells ≈ 5–15% of circulating lymphocytes.","s":10},{"t":"Granulocytes","d":"NEUTROPHIL: phagocytosis, first responders, most numerous. EOSINOPHIL: allergy and parasites. BASOPHIL: like tissue mast cells (★ 'Baso B blood', mast cells in tissue).","s":10},{"t":"Monocyte → macrophage","d":"Monocytes enter tissues during inflammation and become macrophages (tissue macrophage = HISTIOCYTE); they remove material and coordinate inflammation.","s":10},{"t":"Lymphocytes","d":"B: humoral, matures in BONE MARROW, becomes the plasma cell. T: cellular, matures in the THYMUS (★ 'T cells, thymus'). Natural killer: needs NO specific antigen; kills tumor and infected cells.","s":10},{"t":"Markers","d":"T: CD3 (CD4 or CD8). B: CD19, CD20; surface immunoglobulin LOST as a plasma cell. Natural killer: CD56, CD16.","s":10},{"t":"Phagocytosis","d":"Adhere → pseudopods engulf (PHAGOSOME) → fuse with lysosome (PHAGOLYSOSOME) → acid hydrolases digest → residual body → EXOCYTOSIS.","s":10},{"t":"Lymph flow","d":"No pump: SKELETAL MUSCLE movement, THORACIC pressure changes in breathing, pulsing ARTERIES; valves keep it one-way.","s":10},{"t":"B cell → plasma cell","d":"Antigen-INDEPENDENT phase: surface IgM. Antigen-DEPENDENT phase (started by antigen exposure): becomes a PLASMA CELL secreting specific antibody. Antigen SELECTS the matching B cell → clonal expansion → plasma + memory cells.","s":11},{"t":"Primary response","d":"After FIRST exposure; develops over days; IgM rises first; memory cells form.","s":11},{"t":"Secondary response","d":"After RE-EXPOSURE; memory cells → FASTER, STRONGER (★); class-switched antibody, often IgG, higher and longer. ★ High IgM = first exposure; low IgM + high IgG = earlier exposure.","s":11},{"t":"Antibody unit","d":"2 HEAVY + 2 LIGHT chains (light = KAPPA or LAMBDA). Heavy + light VARIABLE regions = antigen-binding site. Heavy-chain CONSTANT region decides the CLASS.","s":11},{"t":"Fab vs Fc","d":"Fab = antigen-binding arms. Fc = constant stem → EFFECTOR functions (complement-binding site on CH2). Papain cuts IgG into 2 Fab + Fc.","s":11},{"t":"IgM","d":"5–10%. PENTAMER (J chain) when secreted. Often FIRST in a new response; AGGLUTINATION; efficient classical complement.","s":11},{"t":"IgG","d":"75–80%, the largest share. Monomer, 4 subclasses. CROSSES THE PLACENTA (★ how maternal immunity reaches the baby); prominent in secondary responses.","s":11},{"t":"IgA · IgD · IgE","d":"IgA 10–15%: secretory DIMER (saliva, tears, colostrum), blocks microbial attachment. IgD &lt;1%: B-cell receptor with IgM. IgE &lt;1%: on MAST CELLS and BASOPHILS → allergy, anaphylaxis, parasites.","s":11},{"t":"Antibody functions","d":"AGGLUTINATION (clumps cells) · NEUTRALIZATION (blocks without destroying ★) · LYSIS (with complement) · PRECIPITATION (cross-links soluble antigen) · OPSONIZATION (coats for phagocytes).","s":11},{"t":"ABO","d":"O red cells carry neither A nor B → O is the universal red-cell donor (★); AB recipients have neither antibody → take O, A, B, AB.","s":11},{"t":"★ CD4 vs CD8","d":"'Four letters in HELP': CD4 = HELPER, reads MHC (major histocompatibility complex) CLASS II. CD8 = CYTOTOXIC, reads CLASS I.","s":12},{"t":"Helper T cell","d":"COORDINATES cellular and humoral responses by cytokines and contact; supports B-cell antibody production; IFN-γ (interferon gamma) activates macrophages.","s":12},{"t":"Cytotoxic T cell","d":"Kills virus-infected, tumor and transplanted cells: PERFORIN + GRANZYMES → target-cell APOPTOSIS.","s":12},{"t":"Regulatory T cell","d":"LIMITS immune activation, maintains SELF-TOLERANCE; many are CD4 expressing FOXP3.","s":12},{"t":"ADCC","d":"Antibody-dependent cellular cytotoxicity: the natural killer cell's CD16 binds the Fc of IgG coating a target.","s":12},{"t":"Hypersensitivity","d":"Humoral or cellular immune reactions that INJURE the body. Numbered by MECHANISM, not severity (★).","s":12},{"t":"Type I","d":"IgE fixed on MAST CELLS/basophils after a sensitizing exposure; re-exposure → HISTAMINE release. Local allergy or ANAPHYLAXIS (bronchospasm, laryngeal edema, hypotension).","s":12},{"t":"Type II","d":"IgG or IgM binds antigen ON cells or tissue → phagocytosis, complement, ADCC; can STIMULATE or BLOCK receptors. ABO incompatibility, anti-glomerular basement membrane disease.","s":12},{"t":"Type III","d":"Antigen–antibody COMPLEXES deposit in tissue or vessel walls. Arthus (local), serum sickness (systemic), LUPUS.","s":12},{"t":"Type IV","d":"Sensitized CD4 or CD8 T CELLS; delayed 24–72 h; granulomas. Contact dermatitis, tuberculosis reactions, transplant rejection.","s":12},{"t":"Complement","d":"Proteins made mostly by the LIVER, circulating as INACTIVE precursors; activation = a regulated CASCADE.","s":13},{"t":"3 pathways (★)","d":"CLASSICAL: C1 binds antigen-bound IgM or IgG. LECTIN: mannose-binding lectin binds microbial carbohydrate. ALTERNATIVE: C3 on permissive surfaces (factor B, factor D, properdin). All CONVERGE ON C3.","s":13},{"t":"3 outcomes","d":"OPSONIZATION (C3b coat) · INFLAMMATION (C3a, C4a, C5a: vasodilation, attraction of phagocytes) · MEMBRANE ATTACK COMPLEX (C5b + C6–C9 pore → lysis). ★ Lysis is only ONE outcome.","s":13},{"t":"Autoimmunity (deck)","d":"No slide of its own: regulatory T cells keep self-tolerance; anti-self antibody can destroy or stimulate/block (type II); lupus is type III; autoantibodies rise with age.","s":13},{"t":"Primary immunodeficiency","d":"INTRINSIC, often GENETIC. X-linked agammaglobulinemia: no B-cell maturation → recurrent PYOGENIC infections. DiGeorge: thymic/T-cell development. Severe combined: T AND B.","s":13},{"t":"Secondary immunodeficiency","d":"From disease, medications, malignancy or poor nutrition.","s":13},{"t":"Age","d":"Neonates: protected by maternal IgG and milk IgA, which wane. Older adults: weaker responses to NEW antigens; more autoantibodies.","s":13},{"t":"Hypoxemia vs hypoxia","d":"Hypoxemia = low BLOOD oxygen (PaO2, arterial oxygen tension; saturation). Hypoxia = low TISSUE oxygenation.","s":14},{"t":"Acute respiratory failure","d":"On room air: PaO2 &lt; 60 mmHg · PaCO2 (arterial carbon dioxide tension) &gt; 50 mmHg · pH &lt; 7.30.","s":14},{"t":"Hypoxic failure","d":"Low oxygen, NORMAL or LOW carbon dioxide: V/Q (ventilation/perfusion) mismatch · SHUNT · decreased diffusion · alveolar hypoventilation · altitude.","s":14},{"t":"Hypercapnic failure","d":"Carbon dioxide not removed: low ventilation or rate · cannot signal (Guillain-Barré, cord injury) · DEAD SPACE (pulmonary embolism, low output) · more carbon dioxide made (fever, burns) · cannot sense it (drugs).","s":14},{"t":"★ Dead space vs shunt","d":"Dead space = ventilation without perfusion. Shunt = perfusion without ventilation.","s":14},{"t":"Pulmonary circulation","d":"HIGH FLOW, LOW PRESSURE: 22/8–25/8 mmHg, mean 15. Pulmonary arteries carry DEOXYGENATED blood (★ names = direction, not oxygen).","s":14},{"t":"Pulmonary hypertension","d":"Mean pulmonary arterial pressure AT REST &gt; 20 mmHg (normal mean ≈ 15).","s":14},{"t":"Routes to it","d":"More FLOW (left-to-right shunt, polycythemia) · more RESISTANCE (hypoxic vasoconstriction, EMBOLISM, fibrosis) · higher LEFT ATRIAL pressure (mitral stenosis).","s":14},{"t":"Vessel changes","d":"MEDIA thickens (more muscle), INTIMA fibroses.","s":14},{"t":"Lung cancers","d":"SQUAMOUS 20–30%, central, sputum cytology. ADENO 35–40% (largest), peripheral. LARGE CELL 5–10%, peripheral. SMALL CELL 15–20%, central, doubles in ~33 days, PARANEOPLASTIC.","s":14},{"t":"Obstructive disease","d":"Increased airflow RESISTANCE: in the WALL (asthma, bronchitis) · LOST PARENCHYMA (emphysema) · in the LUMEN (bronchiectasis, cystic fibrosis, foreign body).","s":15},{"t":"Test pattern","d":"Low FEV1/FVC (forced expiratory volume in 1 second / forced vital capacity) = airflow limitation · high RESIDUAL VOLUME = incomplete emptying · low DLCO (diffusing capacity for carbon monoxide) = a separate gas-transfer question.","s":15},{"t":"Asthma","d":"REVERSIBLE obstruction + airway inflammation + HYPER-RESPONSIVENESS.","s":15},{"t":"Allergic (extrinsic)","d":"IgE on MAST CELLS → histamine, LEUKOTRIENES (slow-reacting substances of anaphylaxis), prostaglandins, bradykinins, eosinophil chemotactic factor, serotonin.","s":15},{"t":"Non-allergic (intrinsic)","d":"Exercise, stress, irritants, aspirin; NEGATIVE skin tests, NORMAL IgE; middle age; worse prognosis.","s":15},{"t":"Asthma airway","d":"Epithelium DENUDED → goblet cells · COLLAGEN under basement membrane · edema · mucus plugs · VAGAL → mucus + bronchoconstriction · REMODELING.","s":15},{"t":"Acute bronchitis","d":"Inflamed trachea/bronchi, mostly VIRAL; more mucus, lost cilia; lasting HYPERIRRITABILITY explains the lingering cough.","s":15},{"t":"Chronic bronchitis (type B)","d":"Productive cough &gt; 3 months a year for 2+ years; smoking 90%; gland + GOBLET hypertrophy; cilia → SQUAMOUS; plugs → V/Q mismatch. BLUE BLOATER = cyanosis + right-heart edema.","s":15},{"t":"Emphysema (type A)","d":"Alveolar wall DESTRUCTION WITHOUT FIBROSIS. PROTEASES from neutrophils/macrophages; smoking inactivates ALPHA-1 ANTITRYPSIN. Lost RADIAL TRACTION → more resistance, less airflow; air trapped → BULLAE. PINK PUFFER.","s":15},{"t":"Emphysema types","d":"CENTRIACINAR: respiratory bronchioles (with chronic bronchitis). PANACINAR: alveoli. PARASEPTAL: peripheral lobules.","s":15},{"t":"Bronchiectasis","d":"Wall DESTRUCTION → DILATED bronchi; congenital (50% related to cystic fibrosis) or acquired; children at risk (soft bronchi). Dilations = infection POCKETS → foul purulent sputum. Shapes: cylindrical, saccular, fusiform.","s":15},{"t":"Cor pulmonale","d":"Hypoxia → pulmonary VASOCONSTRICTION → pulmonary hypertension → RIGHT VENTRICULAR DILATION → right heart failure.","s":15},{"t":"Restrictive = expansion","d":"DECREASED EXPANSION from parenchyma, pleura, chest wall or neuromuscular disease. LOW TOTAL LUNG CAPACITY confirms it (low FVC alone does not).","s":16},{"t":"Interstitial lung disease","d":"Starts with INJURY to alveolar epithelium or capillary endothelium → immune reaction → thick interstitium, COLLAGEN.","s":16},{"t":"3 alveolar patterns","d":"INFLAMMATION (early, REVERSIBLE) → FIBROSIS (fibroblasts, collagen) → DESTRUCTION (end stage: STIFF, NONCOMPLIANT lungs).","s":16},{"t":"Sarcoidosis","d":"ALVEOLAR MACROPHAGES activated by an unknown trigger; NONCASEATING epithelioid GRANULOMAS (lymph nodes, lung); ASTEROID BODIES; abnormal T cells.","s":16},{"t":"Hypersensitivity pneumonitis","d":"Inhaled ORGANIC agents (birds, fungi, wheat weevil); antibodies → TYPE III immune complexes (cell-mediated immunity also contributes); nonsmokers. 'Extrinsic allergic alveolitis'.","s":16},{"t":"Pneumoconiosis","d":"Inhaled INORGANIC dust (coal, silica, asbestos); macrophages cannot clear it → FIBROSIS. Smoking depresses ciliary clearance.","s":16},{"t":"ARDS (acute respiratory distress syndrome)","d":"ATELECTATIC disorder. Alveolar-capillary membrane DAMAGE → LEAKY capillaries → protein-rich NONCARDIOGENIC edema; complement + neutrophil sequestration.","s":16},{"t":"ARDS: 3 processes","d":"Noncardiogenic EDEMA (leaky capillaries) · ATELECTASIS (no SURFACTANT) · HYALINE MEMBRANES (protein deposits).","s":16},{"t":"Pulmonary edema (gathered)","d":"Starling: hydrostatic OUT vs oncotic IN. More capillary pressure or less oncotic pressure → more filtration. Leaky capillaries → noncardiogenic edema.","s":16},{"t":"Primary pneumothorax","d":"TALL, THIN MEN 20–40; SUBPLEURAL BLEBS at the apices rupture; smoking raises risk.","s":17},{"t":"Secondary pneumothorax","d":"Complication of lung disease: asthma, emphysema, cystic fibrosis, pneumonia, tuberculosis.","s":17},{"t":"Tension pneumothorax","d":"Pneumothorax that TRAPS AIR and builds pressure (penetrating or nonpenetrating injury); air ENTERS but cannot LEAVE → lung collapses, mediastinum shifts AWAY → less VENOUS RETURN and CARDIAC OUTPUT.","s":17},{"t":"Pleural effusion causes","d":"Raised HYDROSTATIC pressure (heart failure) · lowered ONCOTIC pressure (nephrotic syndrome, cirrhosis) · lowered pleural pressure (lung collapse). Normal 5–15 mL.","s":17},{"t":"Transudate","d":"Protein ratio &lt; 0.5 · LDH (lactate dehydrogenase) ratio &lt; 0.6 · specific gravity &lt; 1.016. PRESSURE problem: heart failure, cirrhosis, nephrotic syndrome.","s":17},{"t":"Exudate","d":"Protein ratio &gt; 0.5 or LDH ratio &gt; 0.6 (ONE criterion is enough). PERMEABILITY or LYMPHATIC problem: cancer, infection, PULMONARY EMBOLISM, sarcoidosis.","s":17},{"t":"Chylothorax","d":"CHYLE leaking from the THORACIC DUCT (trauma, lymphoma).","s":17},{"t":"Obstructive sleep apnea","d":"≥ 5 events/hour; collapsible PHARYNX closes. APNEA: no airflow ≥ 10 s WITH effort. HYPOPNEA: reduced flow + desaturation or arousal. No flow + NO effort = CENTRAL.","s":17},{"t":"Pneumonia sources","d":"ASPIRATION (gross aspiration → ANAEROBES, abscess) · inhalation (virus, Mycoplasma) · BLOOD-BORNE (right-sided endocarditis, intravenous drug use).","s":17},{"t":"Community vs hospital","d":"Community: at home, or hospitalized &lt; 48 h. Hospital: early (≤ 4 days) susceptible bacteria; LATE = MULTIDRUG-RESISTANT.","s":17},{"t":"Pulmonary embolism (gathered)","d":"Raises DEAD SPACE (hypercapnia) · causes pulmonary hypertension by OBSTRUCTION · causes ARDS and acute respiratory failure · EXUDATIVE effusion.","s":17}],"map":{"clinical-pathophysiology-i-exam-2-cardiac-pathophysiology-quiz-version-2":[0,35,44,35,-1,31,35,1,27,7,50,27,0,32,48,36,36,-1,75,0,-1,-1,16,42,6,36,23,47,48,38],"clinical-pathophysiology-i-exam-2-cardiac-pathophysiology-quiz":[50,11,0,22,22,41,42,-1,32,41,16,30,36,45,49,16,24,18,32,-1,38,33,45,63,46,3,17,50,1,12],"clinical-pathophysiology-i-exam-2-immunity-quiz-version-2":[-1,100,126,110,109,104,126,111,117,119,-1,135,-1,127,116,124,112,114,122,116,111,104,106,107,135,119,114,122,119,131],"clinical-pathophysiology-i-exam-2-immunity-quiz":[111,104,-1,-1,123,119,-1,101,121,137,129,136,119,-1,113,130,114,-1,121,119,102,119,105,131,161,106,129,114,109,103],"clinical-pathophysiology-i-exam-2-pulmonary-pathophysiology-quiz-version-2":[151,177,172,166,147,152,143,141,162,35,155,164,166,172,148,144,176,158,156,160,178,171,139,140,162,150,154,156,158,148],"clinical-pathophysiology-i-exam-2-pulmonary-pathophysiology-quiz":[139,144,165,176,149,179,139,148,155,166,-1,163,156,-1,150,150,161,144,168,159,179,-1,160,169,174,138,169,147,158,166],"clinical-pathophysiology-i-exam-2-vascular-pathophysiology-quiz-version-2":[56,79,97,77,89,75,79,57,70,66,96,73,52,75,96,79,79,65,60,52,76,63,60,90,53,82,68,94,91,86],"clinical-pathophysiology-i-exam-2-vascular-pathophysiology-quiz":[90,-1,56,67,66,98,90,90,60,89,60,75,82,93,97,-1,69,-1,-1,-1,87,63,95,-1,93,65,63,99,65,-1]}};
